  | "startFrameOptional" //Khung đầu/cuối (khung đầu tùy chọn)
  | "text" //văn bản  
  | (`videoReference:${number}` | `imageReference:${number}` | `audioReference:${number}`)[]; //nhiều tham chiếu（số chữ Bảnggiới hạnsố lượng）

interface TextModel {
  name: string;
