declare const logger: (logstring: string) => void;
declare const jsonwebtoken: any;
// ==================== Nhà cung cấpDữ liệu ====================
const vendor: VendorConfig = {
  id: "vidu",
  author: " của Coder",
  description:
    "Nền tảng tạo video AI chính thức của Vidu.\n\n🔗 [Truy cập nền tảng Vidu](https://platform.vidu.cn/login/)",
