    },

    // === Mô hình Tạo Video (Seedance) ===
    {
      name: "Seedance-2.0 (Đồng bộ Âm thanh & Hình ảnh - Số 1)",
      modelName: "doubao-seedance-2-0-260128",
      type: "video",
